# --- storage: paths, upload state, GC, storage.yaml ----------------------


def _canonical_prefix(args):
    from airoa_core.storage.canonical_path import CanonicalPathFields

    return CanonicalPathFields.from_meta_json(args["meta_json"]).canonical_prefix


def _normalize(args):
    from airoa_core.storage.canonical_path import _normalize_path_value

    return _normalize_path_value(args["value"])


def _resolve_s3_prefix(args):
    from airoa_core.storage.upload import _resolve_s3_prefix

    return _resolve_s3_prefix(args["prefix"], args["dir_path"], args["path_rule"])


def _open_state(args):
    """Upstream's UploadStateDB on the caller's file, under a preopen.

    WAL is compiled out of this SQLite and the VFS locks with a `<db>.lock`
    directory, which a force-stop can strand; the host removes it before
    airoa_core starts, so nothing here works around the file.
    """
    from airoa_core.storage.upload_state import UploadStateDB

    return UploadStateDB(args["upload_state_path"])


def _upload_state_needing_upload(args):
    """Which of `recordings` still need sending to `target`.

    Batched because the host asks this about every take on the device on
    every poll, and one crossing beats one per take.
    """
    db = _open_state(args)
    target = args["target"]
    return {
        "needs": [r for r in args["recordings"] if db.should_upload(r, target)],
    }


def _upload_state_pending(args):
    """Upstream's own pending list: rows it holds that still want action.

    A recording with no row at all is not in it — the host learns about
    those from the disk, not from here.
    """
    return {"pending": _open_state(args).get_pending(args["target"])}


def _upload_state_set(args):
    """Record a status for each of `recordings`.

    `etags` is upstream's per-object map, and it describes one recording — so
    it is only meaningful when a single one is named. It is what lets a later
    audit tell "we sent this" apart from "this is still in the bucket".
    """
    db = _open_state(args)
    etags = args.get("etags") or None
    for recording in args["recordings"]:
        db.set_status(recording, args["target"], args["status"], etags=etags)
    return {}


def _upload_state_purge(args):
    """Drop terminal rows older than `max_age_hours`.

    Upstream only ever removes `completed` and `gc_deleted` rows — anything
    still owing action survives — so a purge cannot make a take that was
    never sent look sent. It can make a take the database has forgotten look
    unseen again, which is why the age is long and retention runs first.
    """
    return {"deleted": _open_state(args).purge(float(args["max_age_hours"]))}


def _storage_gc(args):
    """One local GC cycle over *root*.

    Upstream's `run_gc_cycle` lists and deletes through a MinIO client, so it
    cannot run on a local directory. The selection is upstream's
    (`select_for_deletion`, `select_orphans`), but discovery and deletion are
    this function's own: each top-level directory of *root* is one recording,
    and a doomed one is removed with `rmtree`.

    An `upload_state_path` is the caller saying storage state comes from the
    database rather than from a marker file: `storage_marker_exists` is then
    upstream's own "already uploaded to this target" answer, which is what
    lets the marker file go. Without it the filename scan stands, so a caller
    that has no database is not left with a GC that collects nothing.
    """
    import shutil
    from datetime import datetime, timezone

    from airoa_core.storage.config import _parse_target_gc
    from airoa_core.storage.gc import RecordingInfo, select_for_deletion, select_orphans

    cfg = _parse_target_gc(args["gc"])
    if cfg is None:
        return {"deleted": [], "dry_run": False, "total_recordings": 0, "total_bytes": 0}

    state = _open_state(args) if args.get("upload_state_path") else None
    target = args.get("target", "")
    root = args["root"].rstrip("/")
    recordings = []
    for entry in sorted(os.listdir(root)):
        top = os.path.join(root, entry)
        if not os.path.isdir(top):
            continue
        rec = RecordingInfo(prefix=entry + "/")
        latest = None
        for base, _dirs, files in os.walk(top):
            for name in files:
                path = os.path.join(base, name)
                size = os.path.getsize(path)
                mtime = os.path.getmtime(path)
                rec.objects.append((path, size))
                rec.total_size_bytes += size
                if latest is None or mtime > latest:
                    latest = mtime
                if state is None and name == cfg.storage_marker:
                    rec.storage_marker_exists = True
                if name == cfg.completion_marker:
                    rec.completion_marker_exists = True
                    try:
                        with open(path) as f:
                            rec.completed_at = datetime.fromisoformat(
                                json.load(f)["completed_at"]
                            )
                    except Exception:
                        pass
        if latest is not None:
            rec.latest_object_modified = datetime.fromtimestamp(latest, timezone.utc)
        if rec.completed_at is None:
            rec.completed_at = rec.latest_object_modified
        if state is not None:
            rec.storage_marker_exists = not state.should_upload(entry, target)
        recordings.append(rec)

    doomed = {}
    for rec in select_for_deletion(recordings, cfg) + select_orphans(recordings, cfg):
        doomed[rec.prefix] = rec
    deleted = []
    for rec in doomed.values():
        if not cfg.dry_run:
            shutil.rmtree(os.path.join(root, rec.prefix.rstrip("/")))
        deleted.append(rec.prefix.rstrip("/"))
    return {
        "deleted": deleted,
        "dry_run": cfg.dry_run,
        "total_recordings": len(recordings),
        "total_bytes": sum(r.total_size_bytes for r in recordings),
    }


def _parse_gc_strategy(args):
    """Upstream's parsed strategy, as its description plus its truth table.

    ``GCStrategy`` carries a predicate closure that cannot cross JSON, and the
    predicate has three boolean inputs — so all eight answers are the whole of
    it. Index is ``marker * 4 + age * 2 + space``.
    """
    from airoa_core.storage.config import parse_gc_strategy

    strategy = parse_gc_strategy(args["strategy"])
    table = [
        strategy.evaluate(marker=bool(i & 4), age=bool(i & 2), space=bool(i & 1))
        for i in range(8)
    ]
    return {"description": strategy.description, "table": table}


def _gc_diagnostic_level(args):
    from airoa_core.storage.config import _parse_target_gc
    from airoa_core.storage.gc import GCCycleResult, compute_diagnostic_level

    cfg = _parse_target_gc(args["gc"])
    if cfg is None:
        raise ValueError("gc: no block to judge against")
    return compute_diagnostic_level(cfg, GCCycleResult(**args["result"]))


def _load_storage_config(args):
    import yaml
    from airoa_core.storage.config import load_storage_config

    cfg = load_storage_config(args["path"])
    with open(args["path"]) as f:
        raw = yaml.safe_load(f)
    raw_targets = raw.get("targets", {}) if isinstance(raw, dict) else {}

    def row(target):
        body = raw_targets.get(target.name, {})
        if not isinstance(body, dict):
            body = {}
        gc = body.get("gc")
        return {
            "name": target.name,
            "endpoint": target.endpoint,
            "access_key": target.access_key,
            "secret_key": target.secret_key,
            "use_ssl": target.use_ssl,
            "bucket": target.bucket,
            "prefix": target.prefix,
            "path_rule": target.path_rule.value,
            "priority": target.priority.value,
            "region": body.get("region", ""),
            "gc": gc if isinstance(gc, dict) else None,
        }

    return {
        "targets": [row(t) for t in cfg.targets],
        "delete_after_upload": cfg.delete_after_upload,
        "local_retention_hours": cfg.local_retention_hours,
        "state_purge_age_hours": cfg.state_purge_age_hours,
    }


# --- gate: orchestration, condition expressions, config, diagnostics -----


def _diag_level_for(args):
    from airoa_core.gate.escalation import diag_level_for

    return diag_level_for(args["escalation"], args["passed"])


def _escalation_levels(_args):
    from airoa_core.gate.escalation import EscalationLevel

    return {level.name: int(level) for level in EscalationLevel}


def _evaluate_gate(args):
    from airoa_core.gate.escalation import ConditionResult
    from airoa_core.gate.evaluation import GroupState, orchestrate_groups

    class _Fixed:
        def __init__(self, result):
            self._result = ConditionResult(**result)

        def evaluate(self):
            return self._result

    groups = [
        GroupState(
            name=g["name"],
            checkers=[_Fixed(c) for c in g["conditions"]],
            level=g["level"],
            settled=g["settled"],
            settle_is_initial=g["settle_is_initial"],
            settle_start_time=g["settle_start_time"],
            settle_sec=g["settle_sec"],
            recovery_sec=g["recovery_sec"],
        )
        for g in args["groups"]
    ]
    gate_level = orchestrate_groups(
        groups, prev_gate_level=args["prev_gate_level"], now=args["now"]
    )
    def result(r):
        return {
            "name": r.name,
            "passed": r.passed,
            "reason": r.reason,
            "escalation": int(r.escalation),
            "settle_exempt": r.settle_exempt,
        }

    return {
        "gate_level": gate_level,
        "groups": [
            {
                "name": g.name,
                "level": int(g.level),
                "settled": g.settled,
                "settle_is_initial": g.settle_is_initial,
                "settle_start_time": g.settle_start_time,
                "failing": [result(r) for r in g.failing],
                "results": [result(r) for r in g.results],
            }
            for g in groups
        ],
    }


class _Msg:
    """Attribute access over a plain dict, for condition expressions.

    Upstream compiles an expression for ``eval(code, {}, {"msg": msg})`` where
    ``msg`` is a ROS message. The host has JSON, so a dict stands in: nested
    dicts wrap recursively and lists stay lists, so ``msg.effort[0]`` works.
    """

    def __init__(self, body):
        self._body = body

    def __getattr__(self, name):
        try:
            return _wrap(self._body[name])
        except KeyError:
            raise ValueError(f"msg has no field {name!r}")


def _wrap(value):
    if isinstance(value, dict):
        return _Msg(value)
    if isinstance(value, list):
        return [_wrap(v) for v in value]
    return value


def _evaluate_condition(args):
    from airoa_core.gate.expression import compile_condition

    code = compile_condition(args["expr"])
    return bool(eval(code, {"__builtins__": {}}, {"msg": _wrap(args["msg"])}))


def _msg_refs(args):
    from airoa_core.gate.expression import extract_msg_refs

    return extract_msg_refs(args["expr"])


def _load_gate_config(args):
    from airoa_core.gate.config import load_gate_config

    return load_gate_config(args["default_path"], args.get("override_path", ""))


def _gate_diagnostics(args):
    from airoa_core.gate.diagnostics import build_diagnostic_payloads
    from airoa_core.gate.escalation import ConditionResult
    from airoa_core.gate.evaluation import GroupState

    groups = [
        GroupState(
            name=g["name"],
            checkers=[],
            level=g["level"],
            settled=g["settled"],
            settle_is_initial=g["settle_is_initial"],
            settle_start_time=g["settle_start_time"],
            settle_sec=g["settle_sec"],
            recovery_sec=g["recovery_sec"],
            failing=[ConditionResult(**r) for r in g["failing"]],
            results=[ConditionResult(**r) for r in g["results"]],
        )
        for g in args["groups"]
    ]
    return build_diagnostic_payloads(groups, now=args["now"])


# --- backend: profile, episodes, reports, offline queue ------------------


def _pending(backend):
    queue = getattr(backend, "_queue", None)
    return queue.count() if queue is not None else 0


def _local_backend():
    """A backend for a rig with no AIRoA services, which upstream does not
    provide. Nobody logs in, every episode arrives as `pending`, and each
    report has nowhere to go, so it is accepted and dropped.
    """
    from airoa_core.backend.base import BackendBase

    class LocalBackend(BackendBase):
        requires_operator = False

        def get_robot_self(self):
            return {}

        def list_episodes(self):
            return []

        def get_episode(self, episode_id):
            return None

        def repeat_last_episode(self):
            return None

        # An id, because without one the FSM warns on every subtask that the
        # backend will not track it.
        def create_execution(self, episode_id, subtask_id):
            return "local"

        def start_episode(self, episode_id):
            return {}

        def finish_episode(self, episode_id):
            return {}

        def cancel_episode(self, episode_id, reason=""):
            return {}

        def complete_subtask(self, episode_id, subtask_id):
            return {}

        def skip_subtask(self, episode_id, subtask_id):
            return {}

        def start_execution(self, episode_id, subtask_id, execution_id):
            return {}

        def finish_execution(self, episode_id, subtask_id, execution_id):
            return {}

        def cancel_execution(self, episode_id, subtask_id, execution_id):
            return {}

        def update_robot_status(self, payload):
            return {}

    return LocalBackend()


def _backend(args):
    """Upstream's REST client, or the local backend when the caller asks for
    it. `offline_queue_path` is the queue file under a preopen, as yubi's node
    passes it; without one the backend keeps no queue.
    """
    if args.get("local"):
        return _local_backend()
    from airoa_core.backend.api import ApiBackend

    backend = ApiBackend(
        args["base_url"], args["api_key"], offline_queue_path=args.get("offline_queue_path") or None
    )
    # Upstream's `require_active_operator: false`, which its ROS node sets the same way.
    if args.get("operator_optional"):
        backend.requires_operator = False
    return backend


def _backend_me(args):
    from airoa_core.backend.profile import operator_name_from_profile

    profile = _backend(args).get_robot_self() or {}
    model = profile.get("robot_type") or profile.get("type") or profile.get("model") or {}
    if isinstance(model, dict):
        model = model.get("name") or model.get("display_name") or ""
    return {
        "organization": profile.get("organization_name") or "",
        "site": profile.get("site_name") or "",
        "location": profile.get("location_name") or "",
        "robot_type": model,
        "robot_id": profile.get("id") or "",
        "robot_name": profile.get("name") or "",
        "operator": operator_name_from_profile(profile),
    }


def _default_robot_profile(_args):
    from airoa_core.backend.profile import default_robot_profile

    return default_robot_profile()


def _operator_name_from_profile(args):
    from airoa_core.backend.profile import operator_name_from_profile

    return operator_name_from_profile(args["profile"])


def _enrich_episodes(args):
    from airoa_core.backend.episode import enrich_episode

    return [
        enrich_episode(e, operator_name=args.get("operator_name", ""))
        for e in args["episodes"]
    ]


def _select_episode(args):
    from airoa_core.task.episode_selector import EpisodeSelector

    selector = EpisodeSelector(_backend(args), auto_repeat=bool(args.get("auto_repeat", True)))
    episode, reason = selector.pick(
        operator_name=args.get("operator_name", ""),
        completed_ids=set(args.get("completed_ids", [])),
    )
    return {"episode": episode, "reason": reason}


def _list_episodes(args):
    """Every ready episode for this robot, oldest first: the order upstream's
    EpisodeSelector serves them in, since it takes the list's last row.

    The list rows carry no subtasks, so the next episode of each task is
    fetched whole; the rest are only counted until they come up.
    """
    from airoa_core.backend.episode import enrich_episode

    backend = _backend(args)
    completed = set(args.get("completed_ids", []))
    rows = [r for r in reversed(backend.list_episodes() or []) if r.get("id") not in completed]
    fetched = set()
    episodes = []
    for row in rows:
        if row.get("task_id") not in fetched:
            fetched.add(row.get("task_id"))
            row = backend.get_episode(row["id"]) or row
        episodes.append(enrich_episode(row, operator_name=args.get("operator_name", "")))
    return episodes


def _repeat_last(args):
    """A new episode copying the robot's last finished or cancelled one, or
    None while the backend still holds an episode open (409) or has none.
    Fetched whole, for its subtasks.
    """
    from airoa_core.backend.episode import enrich_episode

    backend = _backend(args)
    created = backend.repeat_last_episode()
    if not created:
        return None
    row = backend.get_episode(created["id"]) or created
    return enrich_episode(row, operator_name=args.get("operator_name", ""))


def _report_action(backend, args):
    action = args["action"]
    if action == "start":
        return backend.start_episode(args["episode_id"])
    if action == "finish":
        return backend.finish_episode(args["episode_id"])
    if action == "cancel":
        return backend.cancel_episode(args["episode_id"], args.get("reason", ""))
    raise ValueError(f"unknown action {action!r}")


def _backend_report(args):
    return _report_action(_backend(args), args)


def _backend_report_queued(args):
    """An episode boundary that survives an unreachable backend.

    Upstream passes `queue_on_failure=True` on start/finish/cancel, so a
    connectivity failure or a transient 5xx/408/429 lands in the queue instead
    of being dropped; a permanent 4xx is dropped by upstream on purpose.
    `sent` is upstream saying the call went through — it returns None both for
    a queued failure and for a dropped one, so read `pending` for the backlog.
    """
    backend = _backend(args)
    sent = _report_action(backend, args)
    return {"sent": sent is not None, "pending": _pending(backend)}


def _flush_offline_queue(args):
    """One replay pass over the backlog, in insertion order.

    Upstream drains at most FLUSH_BATCH_SIZE entries per call and throttles
    itself with a backoff kept on the backend object — and there is no such
    object between calls here, so the throttle never carries over. Pacing is
    the host's, which is why `pending` comes back.
    """
    backend = _backend(args)
    backend.flush_offline_queue()
    return {"pending": _pending(backend)}


def _offline_pending(args):
    """How many entries the queue holds. Touches no network."""
    from airoa_core.backend.offline_queue import OfflineQueue

    return {"pending": OfflineQueue(args["offline_queue_path"]).count()}


def _backend_status(args):
    from airoa_core.status.payload import build_robot_status_payload

    return _backend(args).update_robot_status(build_robot_status_payload(**args["inputs"]))


# --- task: FSM, bridge, startup recovery ---------------------------------


def _task(args):
    """One FSM step, on the caller's offline queue.

    The FSM reports subtask completions and executions itself, so without the
    queue those calls are the one class of report an outage still loses. The
    `offline` backend keeps no queue and never touches the file.
    """
    from task_bridge import run

    backend = _backend(args)
    out = run(args, backend)
    out["pending"] = _pending(backend)
    return out


def _bridge(args):
    """Upstream's BridgeStateMachine after every call in `calls`, in order.

    Each operation may run on a different worker, and upstream cannot restore
    a machine from its snapshot, so the caller holds the calls and they are
    replayed. Arguments are converted to the method's annotated types (UUID,
    Outcome, ...), which JSON cannot carry.
    """
    import dataclasses
    import typing

    from airoa_core.task.bridge import BridgeStateMachine

    machine = BridgeStateMachine()
    for call in args["calls"]:
        method = getattr(machine, call["method"])
        types = typing.get_type_hints(method).values()
        method(*(t(a) for t, a in zip(types, call["args"])))
    return json.loads(json.dumps(dataclasses.asdict(machine.snapshot), default=str))


def _recover_step(args):
    """One tick of upstream's `StartupRecoveryPlanner`.

    The planner's only state is its deadline, so instead of keeping a live
    object across calls (there is none between requests) the caller carries
    `start_time` back in. `_start_time` is private because upstream expects
    one long-lived planner; seeding it is what makes a per-call planner
    behave like that one.
    """
    from airoa_core.task.recovery import StartupRecoveryPlanner
    from task_bridge import restore

    ctx = restore(args.get("context", {}))
    planner = StartupRecoveryPlanner(timeout_sec=args.get("timeout_sec", 10.0))
    planner._start_time = args.get("start_time")
    decision = planner.step(
        ctx,
        now_monotonic=args["now_monotonic"],
        is_recording=args.get("is_recording"),
        new_tasks=ctx.new_tasks,
    )
    return {
        "done": decision.done,
        "action": decision.action,
        "reason": decision.reason,
        "assumed_not_recording": decision.is_recording_assumed,
        "start_time": planner._start_time,
    }


def _recover_resume(args):
    from airoa_core.task.recovery import reconstruct_context_from_checkpoint
    from task_bridge import dump, restore

    ctx = restore(args.get("context", {}))
    reconstruct_context_from_checkpoint(ctx, ctx.new_tasks, now_sec=args["now_sec"])
    return dump(ctx)


# --- metadata ------------------------------------------------------------


def _build_metadata(args):
    """One episode's meta.json, built and validated by `MetadataBuilder`.

    Each request builds a fresh MetadataBuilder even in the warm interpreter,
    so the whole episode arrives at once and the setter
    sequence below is fixed. It decides nothing: every value comes from `args`,
    and every `(ok, message)` refusal is re-raised so the Rust side hears it.
    """
    import json as _json

    from airoa_core.metadata.builder import MetadataBuilder
    from airoa_metadata.schemas import load_schema
    from jsonschema import Draft7Validator

    builder = MetadataBuilder()

    def step(ok_and_message):
        ok, message = ok_and_message
        if not ok:
            raise ValueError(message)

    step(builder.initialize())
    step(builder.set_episode_uuid(args["uuid"]))
    step(builder.set_robot(args["robot"]))
    for f in args["files"]:
        step(builder.add_file(f))
    step(builder.set_environment(args["environment"]))
    step(builder.set_runner(args["runner"]))
    step(builder.set_devices(args["devices"]))
    step(builder.extend_programs(args["programs"]))
    step(builder.set_episode(args["episode"]))
    for label in args["labels"]:
        step(builder.add_label(label))
    for segment in args["segments"]:
        step(builder.add_segment(segment))

    ok, built = builder.get_verified()
    if not ok:
        raise ValueError(built)

    document = _json.loads(built)
    Draft7Validator(load_schema("2.0")).validate(document)
    return _json.dumps(document, indent=2)


# --- system_info ---------------------------------------------------------


def _aggregate(kind, rows):
    import dataclasses

    from airoa_core.system_info.aggregator import aggregate_hardware, aggregate_software
    from airoa_core.system_info.types import HardwareInfo, SoftwareInfo

    cls, fold = (
        (HardwareInfo, aggregate_hardware)
        if kind == "hardware"
        else (SoftwareInfo, aggregate_software)
    )
    fields = {f.name for f in dataclasses.fields(cls)}
    items = [cls(**{k: v for k, v in row.items() if k in fields}) for row in rows]
    return [dataclasses.asdict(i) for i in fold(items)]


def _aggregate_hardware(args):
    return _aggregate("hardware", args["items"])


def _aggregate_software(args):
    return _aggregate("software", args["items"])


def _load_manifest(args):
    import dataclasses

    from airoa_core.system_info.config import load_manifest

    manifest = load_manifest(
        combined_path=args.get("combined_path") or None,
        software_path=args.get("software_path") or None,
        hardware_path=args.get("hardware_path") or None,
        env=args.get("env") or {},
    )
    return {
        "software": [dataclasses.asdict(s) for s in manifest.software],
        "hardware": [dataclasses.asdict(h) for h in manifest.hardware],
    }


# --- status --------------------------------------------------------------


def _status_payload(args):
    from airoa_core.status.payload import build_robot_status_payload

    return build_robot_status_payload(**args["inputs"])


class _KeyValue:
    def __init__(self, row):
        self.key = row.get("key", "")
        self.value = row.get("value", "")


class _Entry:
    """One diagnostic status entry, duck-typed as upstream reads it.

    ``level`` is indexed (``status.level[0]``) because a ROS DiagnosticStatus
    carries a single byte there; the host has an int, so it is packed back
    into one byte.
    """

    def __init__(self, row):
        self.name = row.get("name", "")
        self.level = bytes([int(row.get("level", 0))])
        self.message = row.get("message", "")
        self.hardware_id = row.get("hardware_id", "")
        self.values = [_KeyValue(v) for v in row.get("values", [])]


class _Array:
    def __init__(self, rows):
        self.status = [_Entry(r) for r in rows]


def _parse_diagnostics_for_gate(args):
    from airoa_core.status.diagnostics import parse_diagnostics_for_gate

    return parse_diagnostics_for_gate(
        _Array(args["status"]), gate_level=args["gate_level"]
    )


